_service.set_service_url(_base_url)


def preprocess_url(operation_path: str):
    """
    Returns the request url associated with the specified operation path.
    This will be base_url concatenated with a quoted version of operation_path.
    The returned request URL is used to register the mock response so it needs
    to match the request URL that is formed by the requests library.
    """

    # Form the request URL from the base URL and operation path.
    request_url = _base_url + operation_path

    # If the request url does NOT end with a /, then just return it as-is.
    # Otherwise, return a regular expression that matches one or more trailing /.
    if not request_url.endswith('/'):
        return request_url
    return re.compile(request_url.rstrip('/') + '/+')


def test_get_service_url_for_region():
    """
    get_service_url_for_region()
    """
    assert VpcV1.get_service_url_for_region('INVALID_REGION') is None
    assert VpcV1.get_service_url_for_region('au-syd') == 'https://au-syd.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('br-sao') == 'https://br-sao.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('ca-mon') == 'https://ca-mon.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('ca-tor') == 'https://ca-tor.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('eu-de') == 'https://eu-de.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('eu-es') == 'https://eu-es.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('eu-gb') == 'https://eu-gb.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('in-che') == 'https://in-che.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('in-mum') == 'https://in-mum.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('jp-osa') == 'https://jp-osa.iaas.cloud.ibm.com/v1'
    assert VpcV1.get_service_url_for_region('jp-tok') == 'https://jp-tok.iaas.cloud.ibm.com/v1'
